    assert satisfy_must_haves(case, {"unit_price": 40.0, "lead_time_days": 56})["lead_time_days"] == 42
    case = _case([{"field": "volume_per_year", "op": ">=", "value": 22230}], ["unit_price", "volume_per_year"],
